71	    /** Dedicated audit logger; a successful create emits one line here. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /** Request header carrying the client-supplied key that makes a create idempotent. */
75	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
76	
77	    /**
78	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
79	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
80	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
81	     */
82	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
83	
84	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
85	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
86	
87	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
88	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
89	        "mailinator.com", "tempmail.com", "guerrillamail.com");
