131	    /**
132	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
133	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
134	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
135	     */
136	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return onFound.apply(owner);
142	    }
