144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = currentIdempotencyKey();
148	        if (idempotencyKey != null) {
149	            Integer existingId = idempotentCreates.get(idempotencyKey);
150	            if (existingId != null) {
151	                Owner existing = this.clinicService.findOwnerById(existingId);
152	                if (existing != null) {
153	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
154	                }
155	            }
156	        }
157	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
158	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
159	                && response.getBody() != null && response.getBody().getId() != null) {
160	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
161	        }
162	        return response;
163	    }
164	
165	    /**
166	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
167	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
168	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
169	     */
170	    private static String currentIdempotencyKey() {
171	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
172	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
173	            if (key != null && !key.isBlank()) {
174	                return key;
175	            }
176	        }
177	        return null;
178	    }
179	
180	    /**
181	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
182	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
183	     * identity, household and per-city gates are applied, the derived registration attributes are
184	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
185	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
186	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
187	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
188	     * of the create pipeline.
189	     */
190	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        if (!normalizeAndValidateFields(owner)) {
193	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	        }
195	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
196	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
197	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
198	        }
199	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
200	        owner.setRegistrationDate(registrationDate);
201	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
202	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
203	        }
204	        owner.setHouseholdId(householdId(owner));
205	        owner.setIdentityKey(identityKey(owner));
206	        if (isDuplicate(owner)) {
207	            return new ResponseEntity<>(HttpStatus.CONFLICT);
208	        }
209	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
210	        if (!sharesHousehold && hasExistingHousehold(owner)) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (countOwnersInCity(owner.getCity()) >= 50) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        assignRegistrationAttributes(owner, sharesHousehold);
217	        this.clinicService.saveOwner(owner);
218	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
219	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
220	            owner.getMembershipNumber());
221	        HttpHeaders headers = new HttpHeaders();
222	        headers.setLocation(UriComponentsBuilder.newInstance()
223	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
224	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
225	    }
226	
227	    /**
228	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
229	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
230	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
231	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
232	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
233	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
234	     */
235	    private boolean normalizeAndValidateFields(Owner owner) {
236	        if (!normalizeAddressFields(owner)) {
237	            return false;
238	        }
239	        if (owner.getEmail() != null) {
240	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
241	            if (!EMAIL_PATTERN.matcher(email).matches()) {
242	                return false;
243	            }
244	            if (isDisposableEmailDomain(email)) {
245	                return false;
246	            }
247	            owner.setEmail(email);
248	        }
249	        if (!isPostcodeValidForCity(owner)) {
250	            return false;
251	        }
252	        String telephone = normalizeTelephone(owner.getTelephone());
253	        if (telephone == null) {
254	            return false;
255	        }
256	        owner.setTelephone(telephone);
257	        return true;
258	    }
259	
260	    /**
261	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
262	     * returning whether the owner may proceed to creation. The structured fields are preferred when
263	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
264	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
265	     * composed value (the normalized addressLine1, with a single space and the normalized
266	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
267	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
268	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
269	     * address. This is the single place the owner's address is read, canonicalized and written back,
270	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
271	     */
272	    private boolean normalizeAddressFields(Owner owner) {
273	        String line1 = normalizeAddress(owner.getAddressLine1());
274	        if (!line1.isEmpty()) {
275	            String line2 = normalizeAddress(owner.getAddressLine2());
276	            owner.setAddressLine1(line1);
277	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
278	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
279	            return true;
280	        }
281	        String address = normalizeAddress(owner.getAddress());
282	        if (address.isEmpty()) {
283	            return false;
284	        }
285	        owner.setAddress(address);
286	        return true;
287	    }
288	
289	    /**
290	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
291	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
292	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
293	     */
294	    private static boolean isDisposableEmailDomain(String email) {
295	        int at = email.lastIndexOf('@');
296	        if (at < 0) {
297	            return false;
298	        }
299	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
300	    }
301	
302	    /**
303	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
304	     * computed against the owner population rather than carried on the owner itself (currently the
305	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
306	     * listing intentionally omits these flags.
307	     */
308	    private OwnerDto buildOwnerDto(Owner owner) {
309	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
310	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
311	        return ownerDto;
312	    }
