317	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
318	        if (currentOwner == null) {
319	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	        }
321	        currentOwner.setAddress(ownerFieldsDto.getAddress());
322	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
323	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
324	        currentOwner.setCity(ownerFieldsDto.getCity());
325	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
326	        currentOwner.setLastName(ownerFieldsDto.getLastName());
327	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
328	        String email = ownerFieldsDto.getEmail();
329	        if (email != null) {
330	            email = email.trim().toLowerCase(Locale.ROOT);
331	            if (!EMAIL_PATTERN.matcher(email).matches()) {
332	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
333	            }
334	        }
335	        currentOwner.setEmail(email);
336	        this.clinicService.saveOwner(currentOwner);
337	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
338	    }
