416	    /** Matches a well-formed postcode: exactly 4 digits. */
417	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
418	
419	    /**
420	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
421	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
422	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
423	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
424	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
425	     */
426	    private static boolean isPostcodeValidForCity(Owner owner) {
427	        String postcode = owner.getPostcode();
428	        if (postcode == null) {
429	            return true;
430	        }
431	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
432	            return false;
433	        }
434	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
435	        if (range == null) {
436	            return true;
437	        }
438	        int value = Integer.parseInt(postcode);
439	        return value >= range[0] && value <= range[1];
440	    }
441	
442	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
443	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
444	
445	    /**
446	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
447	     * code are kept when present; otherwise country code '+61' is assumed and a single
448	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
449	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
450	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
451	     * Returns {@code null} when the number cannot form a valid E.164 value.
452	     */
453	    private static String normalizeTelephone(String telephone) {
454	        if (telephone == null) {
455	            return null;
456	        }
457	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
458	        String e164;
459	        if (cleaned.startsWith("+")) {
460	            e164 = cleaned;
461	        } else {
462	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
463	            e164 = "+61" + national;
464	        }
465	        if (!E164_PATTERN.matcher(e164).matches()) {
466	            return null;
467	        }
468	        return hasValidNationalNumberLength(e164) ? e164 : null;
469	    }
470	
471	    /**
472	     * Whether the national number of a well-formed E.164 value has the length required for its
473	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
474	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
475	     */
476	    private static boolean hasValidNationalNumberLength(String e164) {
477	        String countryCode = Owner.countryCodeOf(e164);
478	        if (countryCode == null) {
479	            return true;
480	        }
481	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
482	    }
483	
484	    /**
485	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
486	     * code, membership number, household id, namesake count and household member count. Each is
487	     * derived from the owner's already-normalized fields and the existing owner population, so this
488	     * must run before the owner is saved, while the counts still exclude the owner being created.
489	     *
490	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
491	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
492	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
493	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
494	     */
495	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
496	        owner.setCustomerCode(generateCustomerCode(owner));
497	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
498	        owner.setHouseholdId(householdId(owner));
499	        owner.setNamesakeCount(countNamesakes(owner));
500	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
501	        if (declaredMember) {
502	            owner.setPossibleDuplicate(false);
503	            owner.setPossibleDuplicateOf(null);
504	        } else {
505	            assignPossibleDuplicate(owner);
506	        }
507	    }
508	
509	    /**
510	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
511	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
512	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
513	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
514	     * which case the owner is created as a declared household member.
515	     */
516	    private boolean hasExistingHousehold(Owner owner) {
517	        return !findHousemates(owner).isEmpty();
518	    }
519	
520	    /**
521	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
522	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
523	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
524	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
525	     * to the matching owner's id. Runs before save, against the existing owner population.
526	     */
527	    private void assignPossibleDuplicate(Owner owner) {
528	        Integer matchId = findPossibleDuplicateOf(owner);
529	        owner.setPossibleDuplicate(matchId != null);
530	        owner.setPossibleDuplicateOf(matchId);
531	    }
532	
533	    /**
534	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
535	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
536	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
537	     * never matches.
538	     */
539	    private Integer findPossibleDuplicateOf(Owner owner) {
540	        String postcode = owner.getPostcode();
541	        if (postcode == null) {
542	            return null;
543	        }
544	        String lastName = normalizeHouseholdField(owner.getLastName());
545	        String telephone = owner.getTelephone();
546	        return this.clinicService.findAllOwners().stream()
547	            .filter(existing -> !existing.isDeleted())
548	            .filter(existing -> existing.getId() != null
549	                && postcode.equals(existing.getPostcode())
550	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
551	                && !telephone.equals(existing.getTelephone()))
552	            .map(Owner::getId)
553	            .min(Integer::compareTo)
554	            .orElse(null);
555	    }
556	
557	    /**
558	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
559	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
560	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
561	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
562	     * region and the (telephone, last name) pair; only when the computed code collides with an
563	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
564	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
565	     */
566	    private String generateCustomerCode(Owner owner) {
567	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
568	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
569	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
570	        String base = owner.getRegion() + "-" + hash8;
571	        return deduplicateCustomerCode(base);
572	    }
573	
574	    /**
575	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
576	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
577	     * {@code n} of 2 or more that yields a code no existing owner carries.
578	     */
579	    private String deduplicateCustomerCode(String base) {
580	        Set<String> existing = this.clinicService.findAllOwners().stream()
581	            .map(Owner::getCustomerCode)
582	            .filter(code -> code != null)
583	            .collect(java.util.stream.Collectors.toSet());
584	        if (!existing.contains(base)) {
585	            return base;
586	        }
587	        int n = 2;
588	        while (existing.contains(base + "-" + n)) {
589	            n++;
590	        }
591	        return base + "-" + n;
592	    }
593	
594	    /**
595	     * The number of existing owners registered in {@code city}, compared case-insensitively
596	     * with collapsed whitespace.
597	     */
598	    private int countOwnersInCity(String city) {
599	        String normalized = normalizeHouseholdField(city);
600	        return (int) this.clinicService.findAllOwners().stream()
601	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
602	            .count();
603	    }
604	
605	    /**
606	     * The effective registration date to store for a new owner: the date supplied on the request
607	     * when present, otherwise the current server date, in either case rolled forward to a business
608	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
609	     * This single point of resolution is what every registration-date-derived value (the stored
610	     * date, the membership number's year segment, the per-day create-limit) is computed from.
611	     */
612	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
613	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
614	        return toBusinessDay(date);
615	    }
616	
617	    /**
618	     * The fixed list of public holidays that a registration date must not fall on. A date landing
619	     * on one of these is rolled forward, exactly as weekends are.
620	     */
621	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
622	        LocalDate.of(2026, 1, 1),
623	        LocalDate.of(2026, 1, 26),
624	        LocalDate.of(2026, 4, 25),
625	        LocalDate.of(2026, 12, 25),
626	        LocalDate.of(2026, 12, 28));
627	
628	    /**
629	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
630	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
631	     * unchanged.
632	     */
633	    private static LocalDate toBusinessDay(LocalDate date) {
634	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
635	                || PUBLIC_HOLIDAYS.contains(date)) {
636	            date = date.plusDays(1);
637	        }
638	        return date;
639	    }
640	
641	    /**
642	     * Build the membership number '<customerCode>-M<YY>' where YY is the
643	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
644	     * (e.g. 'NSW-1A2B3C4D-M27').
645	     */
646	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
647	        return customerCode + "-M" + membershipYearSegment(registrationDate);
648	    }
649	
650	    /**
651	     * The two-digit year segment stamped into a membership number: the last two digits of the
652	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
653	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
654	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
655	     */
656	    private static String membershipYearSegment(LocalDate registrationDate) {
657	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
658	    }
659	
660	    /**
661	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
662	     * last name, compared case-insensitively.
663	     */
664	    private int countNamesakes(Owner owner) {
665	        String firstName = normalizeHouseholdField(owner.getFirstName());
666	        String lastName = normalizeHouseholdField(owner.getLastName());
667	        return (int) this.clinicService.findAllOwners().stream()
668	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
669	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
670	            .count();
671	    }
672	
673	    /**
674	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
675	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
676	     * unusually high daily signup volume.
677	     */
678	    private boolean isBulkSignupWarning() {
679	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
680	    }
681	
682	    /** The number of existing owners whose registration date is {@code date}. */
683	    private int countOwnersRegisteredOn(LocalDate date) {
684	        return (int) this.clinicService.findAllOwners().stream()
685	            .filter(existing -> date.equals(existing.getRegistrationDate()))
686	            .count();
687	    }
688	
689	    /**
690	     * The single derived key all duplicate detection flows through, formed from the owner's
691	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
692	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
693	     * id is derived, so the household segment is empty at that point. Because the telephone is part
694	     * of the key, two owners in the same household with different telephones resolve to different
695	     * keys and are both allowed.
696	     */
697	    private static String identityKey(Owner owner) {
698	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
699	        String email = owner.getEmail() == null ? "" : owner.getEmail();
700	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
701	        return telephone + "|" + email + "|" + household;
702	    }
703	
704	    /**
705	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
706	     * duplicate condition: the previously separate telephone, email and household checks are now all
707	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
708	     * trips it is rejected with {@code 409 CONFLICT}.
709	     */
710	    private boolean isDuplicate(Owner owner) {
711	        String key = owner.getIdentityKey();
712	        return this.clinicService.findAllOwners().stream()
713	            .filter(existing -> !existing.isDeleted())
714	            .map(Owner::getIdentityKey)
715	            .filter(existing -> existing != null)
716	            .anyMatch(key::equals);
717	    }
718	
719	    /** Common street-type abbreviations expanded during address normalization. */
720	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
721	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
722	
723	    /**
724	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
725	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
726	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
727	     * string when {@code address} is null or blank after normalization.
728	     */
729	    private static String normalizeAddress(String address) {
730	        if (address == null) {
731	            return "";
732	        }
733	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
734	        if (collapsed.isEmpty()) {
735	            return "";
736	        }
737	        StringBuilder sb = new StringBuilder(collapsed.length());
738	        for (String token : collapsed.split(" ")) {
739	            if (sb.length() > 0) {
740	                sb.append(' ');
741	            }
742	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
743	        }
744	        return sb.toString();
745	    }
746	
747	    /**
748	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
749	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
750	     */
751	    private static String normalizeHouseholdField(String value) {
752	        if (value == null) {
753	            return "";
754	        }
755	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
756	    }
757	
758	    /**
759	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
760	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
761	     * key rather than re-derived from the underlying fields here, so the household is described in one
762	     * place and every household-keyed value stays consistent with it.
763	     */
764	    private List<Owner> findHousemates(Owner owner) {
765	        String householdId = householdId(owner);
766	        return this.clinicService.findAllOwners().stream()
767	            .filter(existing -> !existing.isDeleted())
768	            .filter(existing -> householdId(existing).equals(householdId))
769	            .toList();
770	    }
771	
772	    /**
773	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
774	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
775	     */
776	    private int countHouseholdMembers(Owner owner) {
777	        return findHousemates(owner).size() + 1;
778	    }
779	
780	    /**
781	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
782	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
783	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
784	     * string standing in for a missing postcode), so housemates always resolve to the same value
785	     * regardless of registration order, and owners sharing a last name and postcode share it
786	     * automatically.
787	     */
788	    private static String householdId(Owner owner) {
789	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
790	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
791	        return sha256Hex(key).substring(0, 12);
792	    }
793	
794	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
795	    private static String sha256Hex(String input) {
796	        try {
797	            byte[] digest = MessageDigest.getInstance("SHA-256")
798	                .digest(input.getBytes(StandardCharsets.UTF_8));
799	            StringBuilder sb = new StringBuilder(digest.length * 2);
800	            for (byte b : digest) {
801	                sb.append(String.format("%02X", b));
802	            }
803	            return sb.toString();
804	        }
805	        catch (NoSuchAlgorithmException e) {
806	            throw new IllegalStateException("SHA-256 not available", e);
807	        }
808	    }
809	}
